import pg from 'pg';

/** Runs statements on the maintenance database of the test server (CREATE/DROP DATABASE). */
export async function onServer(url: string, statements: readonly string[]): Promise<void> {
  const client = new pg.Client({ connectionString: url });
  await client.connect();
  try {
    for (const statement of statements) await client.query(statement);
  } finally {
    await client.end();
  }
}

/** Database names are generated by us; still, only allow safe identifiers. */
export function quoteIdentifier(name: string): string {
  if (!/^[a-z0-9_]+$/u.test(name)) throw new Error('Unsafe database name');
  return `"${name}"`;
}
